def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_def = sum(1 for x in opp if x == 'D')
    my_def = sum(1 for x in me if x == 'D')

    if opp_def == n:
        return 'D'

    if n == 1:
        return 'D' if last_opp == 'D' else 'C'

    if n <= 4:
        return 'D' if last_opp == 'D' else 'C'

    cnt_c = 0
    cnt_cd = 0
    cnt_d = 0
    cnt_dd = 0

    for i in range(n - 1):
        if me[i] == 'C':
            cnt_c += 1
            if opp[i + 1] == 'D':
                cnt_cd += 1
        else:
            cnt_d += 1
            if opp[i + 1] == 'D':
                cnt_dd += 1

    if n >= 10:
        recent = opp[-10:]
        base = sum(1 for x in recent if x == 'D') / float(len(recent))
    else:
        base = float(opp_def) / float(n)

    if cnt_c > 0:
        pC = (float(cnt_cd) + 2.0 * base) / (float(cnt_c) + 2.0)
    else:
        if opp_def == 0:
            pC = 0.08
        elif base > 0.0:
            pC = base * 0.8
        else:
            pC = 0.35

    if pC < 0.02:
        pC = 0.02
    if pC > 0.98:
        pC = 0.98

    if cnt_d > 0:
        pD = (float(cnt_dd) + 2.0 * base) / (float(cnt_d) + 2.0)
        if opp_def == 0:
            pD = 0.12
        elif base == 0.0 and pD > 0.35:
            pD = 0.35
    else:
        if opp_def == 0:
            pD = 0.12 if my_def > 0 else 0.55
        elif base > 0.4:
            pD = base
        else:
            pD = 0.65

    if pD < 0.02:
        pD = 0.02
    if pD > 0.98:
        pD = 0.98

    r = 100 - n
    if r <= 10:
        if r == 1:
            return 'D'

        vc = 5.0
        vd = 1.0

        for _ in range(2, r):
            dC = 5.0 + (1.0 - pD) * vc + pD * vd
            cC = 3.0 + (1.0 - pC) * vc + pC * vd
            nvc = dC if dC >= cC else cC

            dD = 1.0 + (1.0 - pD) * vc + pD * vd
            cD = 0.0 + (1.0 - pC) * vc + pC * vd
            nvd = dD if dD >= cD else cD

            vc = nvc
            vd = nvd

        q_now = pD if last_me == 'D' else pC
        state = 'D' if q_now > 0.5 else 'C'

        if state == 'C':
            valD = 5.0 + (1.0 - pD) * vc + pD * vd
            valC = 3.0 + (1.0 - pC) * vc + pC * vd
        else:
            valD = 1.0 + (1.0 - pD) * vc + pD * vd
            valC = 0.0 + (1.0 - pC) * vc + pC * vd

        if valD >= valC:
            if last_me == 'D' and opp_def > 0 and pD > 0.22 and rng.random() < 0.75:
                return 'C'
            return 'D'

        return 'C'

    if opp_def == 0:
        if n < 15:
            return 'C'

        if my_def == 0:
            return 'D' if n == 15 else 'C'

        if last_me == 'D':
            if my_def >= 18 and rng.random() < 0.35:
                return 'D'
            if my_def >= 10 and rng.random() < 0.18:
                return 'D'
            return 'C'

        if my_def <= 3:
            prob = 0.16
        elif my_def <= 7:
            prob = 0.13
        elif my_def <= 12:
            prob = 0.16
        else:
            prob = 0.22

        if rng.random() < prob:
            return 'D'

        return 'C'

    if opp_def * 2 > n and n > 10:
        return 'D'

    opp_d3 = sum(1 for i in range(max(0, n - 3), n) if opp[i] == 'D')
    my_d3 = sum(1 for i in range(max(0, n - 3), n) if me[i] == 'D')

    if last_opp == 'D':
        if last_me == 'D':
            if opp_def <= max(2, n // 6):
                if opp_d3 >= 2:
                    return 'D' if rng.random() < 0.55 else 'C'
                return 'C' if rng.random() < 0.8 else 'D'
            return 'D'

        if opp_def <= max(2, n // 10) and my_d3 >= 1:
            return 'C' if rng.random() < 0.8 else 'D'

        if opp_def <= max(1, n // 20) and rng.random() < 0.25:
            return 'C'

        return 'D'

    if n > 15 and opp_def <= max(2, n // 10):
        if last_me == 'D':
            if cnt_d >= 2 and cnt_dd == 0:
                return 'D' if rng.random() < 0.5 else 'C'
            if cnt_d >= 3 and pD < 0.28:
                return 'D' if rng.random() < 0.4 else 'C'
        else:
            if my_def < max(6, n // 8) and rng.random() < 0.05:
                return 'D'

    if pC > pD + 0.35 and n > 20 and opp_def <= n // 2:
        return 'D'

    return 'C'
